<template><section v-if="selection" class="integration-members"><header><h3>Exact cell members</h3><button class="btn subtle" @click="$emit('close')">Close members</button></header><p>{{ selection.selection_id }} · total {{ result?.total??'…' }}</p><p v-if="error" role="alert">{{ error }}</p><a :href="download">All selected members CSV</a><div class="integration-scroll"><table class="table"><thead><tr><th>Native ID</th><th>Entity type</th><th>Source evidence</th></tr></thead><tbody><tr v-for="r in result?.items||[]" :key="r.entity_id"><td><button class="ghost-link" @click="$emit('entity',{...r,species_id:speciesId,report_entity_key:r.entity_id,[r.entity_type+'_id']:r.entity_id})">{{ r.entity_id }}</button></td><td>{{ r.entity_type }}</td><td><details><summary>Original metadata, means and support</summary><pre style="max-width:70ch">{{ JSON.stringify(r,null,2) }}</pre></details></td></tr></tbody></table></div><div class="integration-toolbar"><button class="btn subtle" :disabled="page===1" @click="page--">Previous members</button><span>Page {{ page }}</span><button class="btn subtle" :disabled="page*50>=result?.total" @click="page++">Next members</button></div></section></template>
<script setup>
import {ref,watch,computed} from 'vue';import {integrationExport} from '../../api/integrationVisuals'
const props=defineProps({selection:Object,context:Object,speciesId:String});defineEmits(['close','entity']);const page=ref(1),result=ref(null),error=ref('');let seq=0
watch(()=>props.selection,()=>{page.value=1;load()});watch(page,load)
async function load(){if(!props.selection)return;const s=++seq,id=props.speciesId;try{const r=await props.context.get('members/',{...props.selection,page:page.value,page_size:50});if(s===seq&&id===props.speciesId){result.value=r;if(props.selection.expected!==undefined&&r.total!==props.selection.expected)error.value='Member count differs from displayed cell'}}catch(e){if(s===seq)error.value=e.message}}
const download=computed(()=>integrationExport(props.speciesId,{...props.context.params(),kind:'members',selection_id:props.selection?.selection_id}))
</script>
